using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using PaymentBatchProcessingService.Domain.Entities;
using PaymentBatchProcessingService.Domain.Helpers;

namespace PaymentBatchProcessingService.Infrastructure.DB.Configurations;

public sealed class LegalEntityConfiguration : IEntityTypeConfiguration<LegalEntity>
{
    public void Configure(EntityTypeBuilder<LegalEntity> builder)
    {
        //SQL table name
        builder.ToTable("LegalEntities");

        //Primary key configuration, GUID is generated by the application, not the database
        builder.HasKey(x => x.Id);
        builder.Property(x => x.Id).ValueGeneratedNever();

        //TenantId is not null
        builder.Property(x => x.TenantId).IsRequired();

        //LegalName is not null and has a maximum length defined
        builder.Property(x => x.LegalName).IsRequired().HasMaxLength(LegalEntity.MaxLegalNameLength);

        //RegistrationNumber is not null and has a maximum length defined
        builder.Property(x => x.RegistrationNumber).IsRequired().HasMaxLength(LegalEntity.MaxRegistrationNumberLength);

        //CountryCode is not null, has a maximum length of 2, and is stored as non-Unicode
        builder.Property(x => x.CountryCode).IsRequired().HasMaxLength(Constants.MaxCountryCodeLength).IsUnicode(false);

        //CreatedAtUtc is not null and is stored as UTC in the database
        builder.Property(x => x.CreatedAtUtc).HasColumnType("datetime2")
            .HasConversion(
                value => value,
                value => DateTime.SpecifyKind(value, DateTimeKind.Utc)).IsRequired();

        //Each LegalEntity is associated with one Tenant, and a Tenant can have many LegalEntities
        //The foreign key is TenantId (indexed by default)
        //Deleting a Tenant will not delete its associated LegalEntities
        builder.HasOne<Tenant>().WithMany().HasForeignKey(x => x.TenantId).OnDelete(DeleteBehavior.Restrict);
    }
}
